import { keyboardKey, type StudioKeyboardEvent } from './keyboard-event';
import type { StudioViewRef } from './ui';
import { useEffect, useMemo, useRef, type ReactNode } from 'react';
import { AccessibilityInfo, useColorScheme, type LayoutChangeEvent, type ViewStyle } from 'react-native';
import { ScrollView, Text, View, Menu, SegmentedControl, TabBar, Button, IconButton, KeyValueList, FieldGroup, ErrorMessage, Toolbar, List, ListItem } from './ui';
import { useStore } from 'zustand';
import { createStore } from 'zustand/vanilla';
import { DOCKS, type Dock, type DockAction, type Rect, type Studio } from '@nitro-forge/studio-layout';
import { createStudioWorkspaceStore, MIN_STAGE_HEIGHT, MIN_STAGE_WIDTH, PANEL_IDS, actOnPanel } from './model';
import { ForgeDocumentStage } from './stage';
import { ForgeIcon } from './icons/ForgeIcon';
import { DragGrabHandle } from '@/components/nyc-tron/ui/components/DragGrabHandle';
import { forgeDragTransport } from './drag-transport';
import { useStudioTextScale } from './persona-turret';
import { workspaceThemes, prismThemes, resolveWorkspaceScale, WORKSPACE_DENSITIES, isWorkspaceDensity, type WorkspaceColors, type WorkspaceDensity } from './theme';
import { tokens } from './tokens';
export { createStudioWorkspaceStore } from './model';
export { ForgeDocumentStage } from './stage';

export type WorkspaceRow = { label: string; value: string };
export type WorkspaceAction = { title: string; run: () => Promise<unknown> | unknown };
export type ForgeWorkspaceProps = {
  studioId: Studio; title: string; documentTitle: string; state: unknown;
  rows: WorkspaceRow[]; actions: WorkspaceAction[];
  onUndo: () => Promise<unknown> | unknown; onRedo: () => Promise<unknown> | unknown;
  onSave: () => Promise<unknown> | unknown; onRefresh: () => Promise<unknown> | unknown;
  headerLeading?: ReactNode; headerTrailing?: ReactNode; leadingActions?: ReactNode;
  themeOverrides?: Partial<WorkspaceColors>;
  /** User-selected chrome spacing; independent of window width and document layout. */
  density?: WorkspaceDensity;
  onDensityChange?: (density: WorkspaceDensity) => void;
  busy?: boolean; error?: string | null; children?: ReactNode;
  /** Host storage and blocked geometry are ports; no credentials or documents in presets. */
  loadPreset?: () => Promise<string | null>; persistPreset?: (raw: string) => Promise<void>;
  blockedRegions?: readonly Rect[]; theme?: 'dark' | 'light';
};
const panelNames: Record<string, string> = { outline: 'Document', properties: 'Properties', actions: 'Commands', history: 'History' };
const panelIcons: Record<string, string> = { outline: 'file', properties: 'layers', actions: 'plus', history: 'undo' };
const panelHeadings: Record<string, string> = { outline: 'Document structure', properties: 'Inspector', actions: 'Document commands', history: 'Edit history' };
const appIcons: Record<Studio, string> = { quill: 'text', prism: 'brush', tally: 'table', pitch: 'slide', folio: 'pdf', splice: 'video', cadence: 'music', photo: 'image', motion: 'play', design: 'color-wheel', draft: 'pencil' };

/** Shared inner editor chrome. The host owns and supplies one stable engine document. */
export function ForgeWorkspace(props: ForgeWorkspaceProps) {
  const scale = resolveWorkspaceScale(props.density);
  const systemTheme = useColorScheme();
  const appearance = (props.theme ?? systemTheme) === 'light' ? 'light' : 'dark';
  const canvasStudio = props.studioId === 'prism';
  const colors: WorkspaceColors = { ...(canvasStudio ? prismThemes : workspaceThemes)[appearance], ...props.themeOverrides };
  const store = useMemo(() => createStudioWorkspaceStore(props.studioId), [props.studioId]);
  const ui = useMemo(() => createStore(() => ({ arranging: false, reducedMotion: true, width: tokens.spacing.off1200 as number, height: tokens.spacing.off800 as number })), [props.studioId]);
  const arranging = useStore(ui, s => s.arranging);
  const reducedMotion = useStore(ui, s => s.reducedMotion);
  useEffect(() => {
    let active = true;
    void AccessibilityInfo.isReduceMotionEnabled().then(value => { if (active) ui.setState({ reducedMotion: value }); }).catch(() => {});
    const subscription = AccessibilityInfo.addEventListener('reduceMotionChanged', value => ui.setState({ reducedMotion: value }));
    return () => { active = false; subscription.remove(); };
  }, [ui]);
  const layout = useStore(store, s => s.layout);
  const geometry = useStore(store, s => s.geometry);
  const drag = useStore(store, s => s.drag);
  const status = useStore(store, s => s.status);
  const layoutError = useStore(store, s => s.error);
  const shell = useRef<StudioViewRef>(null);
  const hostRect = useRef<Rect>({ x: 0, y: 0, width: 0, height: 0 });
  const savedPreset = useMemo(() => ({ current: null as string | null }), [store]);
  const operation = useMemo(() => ({ current: false }), [store]);
  // Breakpoints use the stable outer width; the rail must not change its own breakpoint.
  const outerWidth = useStore(ui, s => s.width);
  const outerHeight = useStore(ui, s => s.height);
  const compact = outerWidth < 700;
  // The header's kit controls grow with the text size, so the width that fits
  // them on one row grows too: at 200 % a 390 pt phone gives the host
  // controls their own row instead of clipping Save.
  const textScale = useStudioTextScale();
  const separateHostControls = canvasStudio && outerWidth < 380 * textScale && !!props.headerTrailing;
  // A short landscape host keeps its existing toolbar height. Host menus stay
  // outside the horizontal scroller so their platform popup can open normally.
  const packHostControls = separateHostControls && outerHeight < 500;

  useEffect(() => {
    let active = true;
    void props.loadPreset?.().then(raw => { if (active && raw) { savedPreset.current = raw; store.getState().restorePreset(raw); } })
      .catch(() => { if (active) store.setState({ error: 'Could not load workspace preset' }); });
    return () => { active = false; };
  }, [store, props.loadPreset]);

  const measure = () => shell.current?.measureInWindow((x, y, width, height) => { hostRect.current = { x, y, width, height }; });
  const onLayout = (event: LayoutChangeEvent) => {
    const { width, height } = event.nativeEvent.layout;
    if (width > 0 && height > 0) {
      store.getState().setGeometry({ width, height, minStageWidth: Math.min(MIN_STAGE_WIDTH, width), minStageHeight: width < 700 ? Math.min(160, height * 0.4) : Math.min(MIN_STAGE_HEIGHT, height) });
      if (width < 700) {
        const current = store.getState();
        for (const id of [...current.layout.docks.left, ...current.layout.docks.right]) current.action(id, 'collapse');
      }
      measure();
    }
  };
  const perform = async (label: string, action: () => Promise<unknown> | unknown) => {
    if (operation.current || props.busy) return;
    operation.current = true;
    store.setState({ status: `${label}…`, error: null });
    try { await action(); store.setState({ status: label === 'Save' ? 'Document snapshot generated' : `${label} complete` }); }
    catch (error) { store.setState({ error: error instanceof Error ? error.message : String(error) }); }
    finally { operation.current = false; }
  };
  const button = (label: string, onPress: () => void, selected = false, disabled = false, small = false, iconOnly = false, glyph?: string, primary = false) => {
    const toggled = Object.values(panelNames).includes(label) ? selected : undefined;
    const icon = glyph ? <ForgeIcon name={glyph} size={18} selected={selected} disabled={disabled}
      appearance={appearance} color={primary ? colors.ink : selected ? colors.accent : colors.muted}
      selectedColor={primary ? colors.ink : colors.accent} surfaceColor={primary ? colors.accent : selected ? colors.soft : colors.base} reducedMotion={reducedMotion} /> : undefined;
    const shared = { onPress, disabled, targetSize: scale.size.target, ...(toggled === undefined ? {} : { selected: toggled }), cornerRadius: scale.radius.control,
      variant: primary ? 'primary' as const : 'ghost' as const, tone: 'carolina' as const,
      // A transparent edge keeps each button's shape under Windows High Contrast.
      className: (selected && !primary ? 'rounded-sm border border-transparent bg-ink-800' : 'rounded-sm border border-transparent') + (props.density === 'comfortable' ? ' min-h-12 min-w-12' : '') };
    return iconOnly ? <IconButton key={label} {...shared} size={primary ? 'md' : 'sm'} aria-label={label} icon={icon} />
      : <Button key={label} {...shared} size={small ? 'sm' : 'md'} title={label} icon={icon} />;
  };
  const action = (id: string, kind: DockAction) => actOnPanel(store, id, kind, compact);
  const fraction = (dock: Dock) => layout.sizes[dock === 'left' ? 'leftFraction' : dock === 'right' ? 'rightFraction' : 'bottomFraction'];

  function renderPanel(id: string, dock?: Dock) {
    return <View style={{ flex: 1, minHeight: 0, backgroundColor: colors.raised }}>
      {(!dock || arranging) && <Toolbar density="compact" title={panelHeadings[id] ?? panelNames[id] ?? id} tone="carolina"
        leading={arranging ? <DragHandle id={id} store={store} measure={measure} hostRect={hostRect} blockedRegions={props.blockedRegions} color={colors.muted} /> : undefined}
        actions={button(`Hide ${panelNames[id]}`, () => action(id, 'collapse'), false, false, true, true, 'close')} />}
      <ScrollView style={{ flex: 1 }} contentContainerStyle={{ paddingHorizontal: scale.space.group, paddingTop: dock && !arranging ? scale.space.group : 0, paddingBottom: scale.space.group + tokens.spacing.off2, gap: scale.space.inset + tokens.spacing.off2 }}>
        {id === 'outline' && <>
          <View style={{ flexDirection: 'row', gap: scale.space.element + tokens.spacing.off2, alignItems: 'center', padding: scale.space.inset, backgroundColor: colors.base, borderRadius: scale.radius.control }}><ForgeIcon name={appIcons[props.studioId]} size={tokens.size.iconToolbar} color={colors.accent} reducedMotion={reducedMotion} /><Text style={{ color: colors.text, fontSize: scale.type.body, fontWeight: tokens.fontWeight.medium, flex: 1 }}>{props.documentTitle}</Text></View>
          <List tone="carolina">{props.rows.map((row, index) => <ListItem key={`${index}:${row.label}`} supportingText={row.value || 'Empty paragraph'}>{row.label}</ListItem>)}</List>
        </>}
        {id === 'properties' && <View style={{ borderRadius: scale.radius.control, overflow: 'hidden' }}><FieldGroup>
          <FieldGroup.Section title="Document details" tone="carolina">
            <KeyValueList columns={1} surface="night" items={props.rows.map((row, index) => ({ key: `${index}:${row.label}`, label: row.label, value: row.value || 'Empty' }))} />
          </FieldGroup.Section>
        </FieldGroup></View>}
        {id === 'actions' && <>
          <Text style={{ color: colors.muted, fontSize: tokens.text.label, lineHeight: tokens.leading.off19 }}>Run an operation on this document.</Text>
          {props.actions.map(item => <View key={item.title} style={{ backgroundColor: colors.base, borderWidth: tokens.borderWidth.hairline, borderColor: colors.line, borderRadius: scale.radius.control }}>
            {button(item.title, () => { void perform(item.title, item.run); }, false, props.busy)}
          </View>)}
        </>}
        {id === 'history' && <View style={{ gap: tokens.spacing.off10 }}>
          <Text style={{ color: colors.text, fontSize: tokens.text.off13 }}>Document history</Text>
          <Text style={{ color: colors.muted, fontSize: tokens.text.label, lineHeight: tokens.leading.off19 }}>Undo and redo your document edits.</Text>
          <View style={{ flexDirection: 'row', gap: tokens.spacing.fixedElement }}>{button('Undo', () => { void perform('Undo', props.onUndo); }, false, props.busy)}{button('Redo', () => { void perform('Redo', props.onRedo); }, false, props.busy)}</View>
        </View>}
        {arranging && <View style={{ borderTopWidth: tokens.borderWidth.hairline, borderTopColor: colors.line, paddingTop: scale.space.inset, gap: scale.space.stack }}>
          <Text style={{ color: colors.muted, fontSize: tokens.text.off11, letterSpacing: tokens.tracking.off1 }}>PANEL POSITION</Text>
          <SegmentedControl aria-label={`Dock position for ${panelNames[id] ?? id}`} value={dock ?? ''}
            options={DOCKS.map(zone => ({ value: zone, label: zone[0]!.toUpperCase() + zone.slice(1) }))}
            onChange={zone => { if (DOCKS.includes(zone as Dock)) action(id, `move-${zone as Dock}`); }}
            tone="royal" className="w-full rounded-sm" segmentClassName="rounded-sm" />
          <View style={{ flexDirection: 'row', flexWrap: 'wrap' }}>
            {button('Move before', () => action(id, 'move-before'), false, false, true)}
            {button('Move after', () => action(id, 'move-after'), false, false, true)}
            {dock && button(dock === 'bottom' ? 'Shorter' : 'Narrower', () => { store.getState().resize(dock, Math.max(0.1, fraction(dock) - 0.04)); }, false, false, true)}
            {dock && button(dock === 'bottom' ? 'Taller' : 'Wider', () => { store.getState().resize(dock, fraction(dock) + 0.04); }, false, false, true)}
          </View>
        </View>}
      </ScrollView>
    </View>;
  }
  const dockView = (dock: Dock, style: ViewStyle) => {
    const panels = layout.docks[dock].filter(id => !layout.collapsed.includes(id));
    if (!panels.length) return null;
    const active = panels.includes(layout.activeTabs[dock] ?? '') ? layout.activeTabs[dock]! : panels[0]!;
    return <View key={dock} testID={`dock-${dock}`} style={[{ minHeight: 0, padding: scale.space.element, backgroundColor: colors.deep }, style]}>
      <View style={{ flex: 1, minHeight: 0, borderColor: colors.line, borderWidth: tokens.borderWidth.hairline, borderRadius: scale.radius.panel, overflow: 'hidden', backgroundColor: colors.raised }}>
        <View style={{ flexDirection: 'row', alignItems: 'center', padding: scale.space.stack + 1, borderBottomWidth: tokens.borderWidth.hairline, borderBottomColor: colors.line }}>
          <View style={{ flex: 1, minWidth: 0 }}>
            <TabBar semantics="tabs" density="compact" aria-label={`${dock} dock panels`} tone="royal" className="rounded-sm overflow-hidden" tabs={panels.map(id => ({
              key: id, label: panelNames[id] ?? id, active: active === id,
              onPress: () => action(id, 'activate'),
              icon: <ForgeIcon name={panelIcons[id] ?? 'file'} size={17} color={active === id ? tokens.color.iconOnActive : colors.muted} reducedMotion={reducedMotion} />,
            }))} />
          </View>
          {!arranging && button(`Hide ${panelNames[active]}`, () => action(active, 'collapse'), false, false, true, true, 'close')}
        </View>
        {renderPanel(active, dock)}
      </View>
    </View>;
  };

  const keyboardProps = { onKeyDown: (event: StudioKeyboardEvent) => { if (keyboardKey(event) === 'Escape') { store.getState().cancelDrag(); } } };
  const rail = <View style={{ width: scale.size.rail, backgroundColor: colors.base, borderRightWidth: tokens.borderWidth.hairline, borderRightColor: colors.line, alignItems: 'center', paddingVertical: scale.space.inset + tokens.spacing.off2 }}>
    <View style={{ alignItems: 'center', gap: scale.space.inset, paddingBottom: scale.space.group }}>
      {PANEL_IDS.filter(id => id !== 'history').map(id => <View key={id} style={{ alignItems: 'center', gap: tokens.spacing.fixedStack }}>
        {button(panelNames[id]!, () => action(id, layout.collapsed.includes(id) ? 'activate' : 'collapse'), !layout.collapsed.includes(id), false, false, true, panelIcons[id])}
        <Text style={{ color: !layout.collapsed.includes(id) ? colors.accent : colors.muted, fontSize: tokens.text.off9, fontWeight: !layout.collapsed.includes(id) ? tokens.fontWeight.semibold : '400' }}>{id === 'properties' ? 'Inspect' : id === 'actions' ? 'Commands' : 'Document'}</Text>
      </View>)}
    </View>
    <View style={{ width: tokens.spacing.fixedStatus, height: tokens.borderWidth.hairline, backgroundColor: colors.line }} />
    <View style={{ alignItems: 'center', gap: scale.space.stack, paddingTop: scale.space.group }}>
      {button('History', () => action('history', layout.collapsed.includes('history') ? 'activate' : 'collapse'), !layout.collapsed.includes('history'), false, false, true, panelIcons.history)}
      <Text style={{ color: layout.collapsed.includes('history') ? colors.muted : colors.accent, fontSize: tokens.text.off9 }}>History</Text>
    </View>
  </View>;
  return <View {...keyboardProps} onLayout={event => {
    const { width, height } = event.nativeEvent.layout;
    if (width > 0 && height > 0 && (width !== ui.getState().width || height !== ui.getState().height)) ui.setState({ width, height });
  }} testID="forge-workspace" style={{ flex: 1, minHeight: 0, backgroundColor: canvasStudio ? colors.deep : colors.base }}>
    <View style={{ paddingHorizontal: compact ? scale.space.inset : scale.space.group + scale.space.stack, borderBottomWidth: canvasStudio ? 0 : tokens.borderWidth.hairline, borderBottomColor: colors.line, flexDirection: 'row', alignItems: 'center', gap: compact ? scale.space.element : scale.space.group, minHeight: canvasStudio ? scale.size.canvasHeader : scale.size.header, ...(canvasStudio ? { backgroundColor: colors.base, margin: scale.space.element, marginBottom: 0, borderRadius: scale.radius.control, boxShadow: tokens.shadow.floatSm } : {}) }}>
      {props.headerLeading}
      <View style={{ width: separateHostControls ? tokens.spacing.fixedCanvas : 38, height: separateHostControls ? tokens.spacing.fixedCanvas : 38, backgroundColor: colors.soft, borderRadius: scale.radius.control, alignItems: 'center', justifyContent: 'center' }}>
        <ForgeIcon name={appIcons[props.studioId]} size={separateHostControls ? tokens.size.iconToolbar : 23} selected color={colors.accent} selectedColor={colors.accent} surfaceColor={colors.soft} reducedMotion={reducedMotion} />
      </View>
      <View style={{ flex: 1, minWidth: tokens.spacing.off40, gap: tokens.spacing.fixedStack }}>
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: tokens.spacing.fixedElement }}><Text numberOfLines={1} style={{ color: colors.muted, fontSize: tokens.text.off11, fontWeight: tokens.fontWeight.semibold, letterSpacing: tokens.tracking.off0_4, flexShrink: 1 }}>{props.title}</Text>{!compact && <><Text style={{ color: colors.line, fontSize: tokens.text.off11 }}> / </Text><Text style={{ color: colors.muted, fontSize: tokens.text.off11 }}>{props.busy ? 'Working…' : 'Document'}</Text></>}</View>
        <Text numberOfLines={1} style={{ color: colors.text, fontWeight: tokens.fontWeight.semibold, fontSize: compact ? tokens.text.off13 : tokens.text.off15 }}>{props.documentTitle}</Text>
      </View>
      {!separateHostControls && props.headerTrailing}
      {button('Save', () => { void perform('Save', props.onSave); }, true, props.busy, false, compact, 'save', true)}
    </View>
    {separateHostControls && !packHostControls && <View testID="workspace-host-controls" style={{ minHeight: scale.size.target, flexDirection: 'row', alignItems: 'center', justifyContent: 'flex-end', paddingHorizontal: scale.space.inset }}>
      {props.headerTrailing}
    </View>}
    <View style={{ flexDirection: 'row', borderBottomWidth: canvasStudio ? 0 : tokens.borderWidth.hairline, borderBottomColor: colors.line, alignItems: 'center', paddingHorizontal: compact ? scale.space.element : scale.space.group, minHeight: canvasStudio ? scale.size.canvasToolbar : scale.size.toolbar }}>
      <ScrollView horizontal style={{ flex: 1 }} contentContainerStyle={{ alignItems: 'center', gap: scale.space.stack }}>
        {props.leadingActions}
        <View style={{ width: tokens.borderWidth.hairline, height: tokens.spacing.off22, backgroundColor: colors.line, marginHorizontal: tokens.spacing.fixedElement }} />
        {button('Undo', () => { void perform('Undo', props.onUndo); }, false, props.busy, true, true, 'undo')}
        {button('Redo', () => { void perform('Redo', props.onRedo); }, false, props.busy, true, true, 'redo')}
      </ScrollView>
      {packHostControls && <View testID="workspace-host-controls" style={{ flexDirection: 'row', alignItems: 'center' }}>{props.headerTrailing}</View>}
      <Menu title="Workspace" triggerLabel="Workspace" actions={[
        ...(props.onDensityChange ? WORKSPACE_DENSITIES.map(density => ({id:'density:'+density,title:'Density: '+density+(density===(props.density??'standard')?' (current)':'')})) : []),
        ...PANEL_IDS.map(id => ({ id: `panel:${id}`, title: `${layout.collapsed.includes(id) ? 'Show' : 'Hide'} ${panelNames[id]}` })),
        { id: 'arrange', title: arranging ? 'Done arranging' : 'Arrange panels' },
        { id: 'save', title: 'Save layout' }, { id: 'restore', title: 'Restore layout' },
        { id: 'reset', title: 'Reset layout' }, { id: 'refresh', title: 'Refresh', disabled: !!props.busy },
      ]} onAction={id => {
        if (id.startsWith('density:')) { const density=id.slice(8); if(isWorkspaceDensity(density)) props.onDensityChange?.(density); }
        if (id.startsWith('panel:')) { const panel = id.slice(6); if (PANEL_IDS.includes(panel as typeof PANEL_IDS[number])) action(panel, layout.collapsed.includes(panel) ? 'activate' : 'collapse'); }
        if (id === 'arrange') { ui.setState({ arranging: !arranging }); store.getState().cancelDrag(); }
        if (id === 'save') void perform('Save layout', async () => { const raw = store.getState().savePreset(); if (raw) { savedPreset.current = raw; await props.persistPreset?.(raw); } });
        if (id === 'restore') { if (savedPreset.current) store.getState().restorePreset(savedPreset.current); else store.setState({ error: 'Save a layout first' }); }
        if (id === 'reset') store.getState().reset();
        if (id === 'refresh') void perform('Refresh', props.onRefresh);
      }}><View style={{ minHeight: scale.size.target, minWidth: scale.size.target, paddingHorizontal: scale.space.element + tokens.spacing.off2, justifyContent: 'center' }}><Text style={{ color: colors.text, fontSize: tokens.text.label }}>Workspace</Text></View></Menu>
    </View>
    {arranging && <View style={{ flexDirection: 'row', backgroundColor: colors.soft, paddingHorizontal: scale.space.group, alignItems: 'center', justifyContent: 'space-between' }}><Text style={{ color: colors.accent, fontSize: tokens.text.off11 }}>Drag a panel to an edge, or use its move controls.</Text>{button('Done arranging', () => { ui.setState({ arranging: false }); store.getState().cancelDrag(); })}</View>}
    <View style={{ flex: 1, minHeight: 0, flexDirection: 'row' }}>
      {!compact && !canvasStudio && rail}
    <View ref={shell} onLayout={onLayout} testID="workspace-host" style={{ flex: 1, minHeight: 0, position: 'relative' }}>
      <View style={{ flex: 1, minHeight: 0, flexDirection: 'row' }}>
        {dockView('left', { width: `${layout.sizes.leftFraction * 100}%` })}
        <View testID="document-stage" style={{ flex: 1, minWidth: 0, minHeight: 0, backgroundColor: colors.deep }}>
          {props.children ?? <ForgeDocumentStage studioId={props.studioId} state={props.state} theme={appearance} />}
        </View>
        {dockView('right', { width: `${layout.sizes.rightFraction * 100}%` })}
        {/* Sized by its buttons, so grown text widens the column and the stage gives way, rather than the buttons spilling over the stage. */}
        {canvasStudio && !compact && <View accessibilityLabel="Studio panels" style={{ minWidth: scale.size.canvasRail, paddingHorizontal: tokens.spacing.off3, alignItems: 'center', gap: scale.space.stack, paddingTop: scale.space.inset, backgroundColor: colors.deep }}>
          <View style={{ paddingVertical: tokens.spacing.fixedStack, gap: tokens.spacing.off2, backgroundColor: colors.base, borderWidth: tokens.borderWidth.hairline, borderColor: colors.line, borderRadius: scale.radius.control }}>
            {(['properties', 'actions', 'history'] as const).map(id => button(panelNames[id]!, () => action(id, layout.collapsed.includes(id) ? 'activate' : 'collapse'), !layout.collapsed.includes(id), false, true, true, panelIcons[id]))}
          </View>
        </View>}
      </View>
      {dockView('bottom', { height: `${layout.sizes.bottomFraction * 100}%` })}
      {layout.floating.filter(f => !layout.collapsed.includes(f.panelId)).map(f => <View key={f.panelId} style={{ position: 'absolute', left: `${f.rect.x * 100}%`, top: `${f.rect.y * 100}%`, width: `${f.rect.width * 100}%`, height: `${f.rect.height * 100}%`, borderWidth: tokens.borderWidth.hairline, borderColor: colors.accent, borderRadius: scale.radius.panel, overflow: 'hidden' }}>{renderPanel(f.panelId)}</View>)}
      {drag?.preview && <View pointerEvents="none" testID="dock-preview" style={{ position: 'absolute', left: drag.preview.rect.x - hostRect.current.x, top: drag.preview.rect.y - hostRect.current.y, width: drag.preview.rect.width, height: drag.preview.rect.height, backgroundColor: colors.accent + '30', borderColor: colors.accent, borderWidth: tokens.borderWidth.strong, alignItems: 'center', justifyContent: 'center' }}><Text style={{ color: colors.text }}>Dock {drag.preview.dock}</Text></View>}
      {drag && <View style={{ position: 'absolute', alignSelf: 'center', top: tokens.spacing.fixedElement, backgroundColor: colors.raised, borderWidth: tokens.borderWidth.hairline, borderColor: colors.accent }}>{button('Cancel move', () => store.getState().cancelDrag())}</View>}
    </View>
    </View>
    {compact && !canvasStudio && <View style={{ flexDirection: 'row', borderTopWidth: tokens.borderWidth.hairline, borderTopColor: colors.line, backgroundColor: colors.base, paddingBottom: tokens.spacing.off6 }}>
      {PANEL_IDS.map(id => <View key={id} style={{ flex: 1, alignItems: 'center' }}>
        {button(panelNames[id]!, () => action(id, layout.collapsed.includes(id) ? 'activate' : 'collapse'), !layout.collapsed.includes(id), false, true, true, panelIcons[id])}
        <Text style={{ color: layout.collapsed.includes(id) ? colors.muted : colors.accent, fontSize: scale.type.micro }}>{id === 'properties' ? 'Inspect' : id === 'actions' ? 'Tools' : panelNames[id]}</Text>
      </View>)}
    </View>}
    {(!canvasStudio || props.error || layoutError || /complete|generated|failed|…/.test(status)) && <View style={{ minHeight: scale.size.status, paddingHorizontal: scale.space.group, paddingVertical: scale.space.element / 2 + tokens.spacing.off2, borderTopWidth: tokens.borderWidth.hairline, borderTopColor: colors.line, ...(canvasStudio ? { position: 'absolute', left: tokens.spacing.off76, right: tokens.spacing.off76, bottom: tokens.spacing.off84, zIndex: tokens.z.chrome, backgroundColor: colors.raised, borderRadius: scale.radius.control, borderWidth: tokens.borderWidth.hairline, borderColor: colors.line, boxShadow: tokens.shadow.floatMd } : {}) }}>
      {props.error || layoutError ? <ErrorMessage surface="night" message={props.error || layoutError || ''} /> : <Text accessibilityLiveRegion="polite" selectable style={{ color: colors.muted, fontSize: tokens.text.off11 }}>{status}</Text>}
    </View>}
  </View>;
}

// Stable component identity keeps the responder alive while preview state updates.
function DragHandle({ id, store, measure, hostRect, blockedRegions, color }: {
  id: string; store: ReturnType<typeof createStudioWorkspaceStore>; measure: () => void;
  hostRect: { current: Rect }; blockedRegions: readonly Rect[] | undefined; color: string;
}) {
  return <DragGrabHandle label={`Drag ${panelNames[id]} to a dock edge`} transport={forgeDragTransport}
    onStart={() => { measure(); store.getState().beginDrag(id); }}
    onMove={point => store.getState().previewDrag({ point, host: hostRect.current,
      ...(blockedRegions ? { blockedRegions } : {}) })}
    onCommit={() => { store.getState().commitDrag(); }}
    onCancel={() => store.getState().cancelDrag()}><ForgeIcon name="menu" size={tokens.size.iconSm} color={color} reducedMotion /></DragGrabHandle>;
}

export { QuillTextEditor, type QuillTextEditorHandle, type QuillTextEditorProps } from './text-editor';

import { createStore } from 'zustand/vanilla';
import {
  applyDockAction, collapsePanel, createWorkspace, dockPanel, parsePreset,
  resizeDock, resolveDockDropPreview, serializePreset, stageFits,
  type Dock, type DockAction, type DockDropPreview, type Geometry, type Layout,
  type Point, type Rect, type Studio,
} from '@nitro-forge/studio-layout';

/** Panels available in each studio workspace. */
export const PANEL_IDS = ['outline', 'properties', 'actions', 'history'] as const;
/** A panel managed by {@linkcode createStudioWorkspaceStore}. */
export type PanelId = typeof PANEL_IDS[number];
/** Panel registry used to validate workspace presets and transitions. */
export const KNOWN_PANELS: ReadonlySet<string> = new Set(PANEL_IDS);
/** Default minimum drawing-stage width, in logical pixels. */
export const MIN_STAGE_WIDTH = 320;
/** Default minimum drawing-stage height, in logical pixels. */
export const MIN_STAGE_HEIGHT = 240;

/** Create an independent default panel layout for a studio. */
export function createDefaultLayout(studioId: Studio = 'prism'): Layout {
  const layout = createWorkspace(studioId);
  return { ...layout,
    docks: { left: ['outline'], right: ['properties', 'actions'], bottom: ['history'] },
    activeTabs: studioId === 'prism' ? {} : studioId === 'quill' ? { left: 'outline' } : { left: 'outline', right: 'properties' },
    collapsed: studioId === 'prism' ? ['outline', 'properties', 'actions', 'history'] : studioId === 'quill' ? ['properties', 'actions', 'history'] : ['history'],
    sizes: { leftFraction: .18, rightFraction: .22, bottomFraction: .27 },
  };
}

/** Collapse controls without dropping their placement when a measured host shrinks. */
export function fitWorkspace(layout: Layout, geometry: Geometry): Layout | null {
  if (![geometry.width, geometry.height, geometry.minStageWidth, geometry.minStageHeight]
    .every(value => Number.isFinite(value) && value > 0)) return null;
  let next = layout;
  // Compact hosts reserve the full width for the document and bottom panels.
  // Apply this here so reset and preset restore follow the same measured policy.
  if (geometry.width < 700) {
    for (const panel of [...next.docks.left, ...next.docks.right]) {
      const result = collapsePanel(next, panel, true);
      if (result.ok) next = result.layout;
    }
  }
  for (const panel of ['history', 'actions', 'properties', 'outline']) {
    if (stageFits(next, geometry)) return next;
    const result = collapsePanel(next, panel, true);
    if (result.ok) next = result.layout;
  }
  // A host smaller than the requested stage still gets all panel space released.
  return next;
}

type PreviewInput = { point: Point; host: Rect; blockedRegions?: readonly Rect[] };
/** Observable workspace state and commands from {@linkcode createStudioWorkspaceStore}. */
export type WorkspaceState = {
  layout: Layout;
  geometry: Geometry | null;
  drag: { panelId: string; preview: DockDropPreview | null } | null;
  error: string | null;
  status: string;
  action: (panelId: string, action: DockAction) => boolean;
  resize: (dock: Dock, fraction: number) => boolean;
  setGeometry: (geometry: Geometry) => void;
  beginDrag: (panelId: string) => void;
  previewDrag: (input: PreviewInput) => void;
  cancelDrag: () => void;
  commitDrag: () => boolean;
  savePreset: () => string | null;
  restorePreset: (raw: string) => boolean;
  reset: () => void;
};

/** Create per-workspace state; subscribe with selectors in the host UI.
 * Drag previews never change the committed layout. A commit consumes its preview.
 * No document data or native resources are retained by this store.
 */
export function createStudioWorkspaceStore(studioId: Studio = 'prism') {
  return createStore<WorkspaceState>((set, get) => ({
    layout: createDefaultLayout(studioId), geometry: null, drag: null, error: null,
    status: 'Workspace ready',
    action(panelId, action) {
      const { layout, geometry } = get();
      const result = applyDockAction(layout, panelId, action, KNOWN_PANELS, geometry ?? undefined);
      // expand is deliberately geometry-checked here: the layout primitive only
      // applies that check to activate, whereas every visible expansion must fit.
      if (!result.ok || (geometry && !stageFits(result.layout, geometry) && action !== 'collapse')) {
        set({ error: result.ok ? 'no-stage-space' : result.reason, drag: null });
        return false;
      }
      set({ layout: result.layout, drag: null, error: null, status: `${({ outline: "Document", properties: "Inspector", actions: "Commands", history: "History" } as Record<string, string>)[panelId] ?? "Panel"} ${action === "collapse" ? "hidden" : "opened"}` });
      return true;
    },
    resize(dock, fraction) {
      const { layout, geometry } = get();
      if (!geometry) { set({ error: 'Measure the workspace before resizing' }); return false; }
      const result = resizeDock(layout, dock, fraction, geometry);
      if (!result.ok) { set({ error: result.reason }); return false; }
      set({ layout: result.layout, drag: null, error: null, status: `${dock} dock resized` });
      return true;
    },
    setGeometry(geometry) {
      const layout = fitWorkspace(get().layout, geometry);
      if (!layout) { set({ error: 'invalid-geometry', drag: null }); return; }
      set({ geometry: { ...geometry }, layout, drag: null, error: null,
        status: stageFits(layout, geometry) ? 'Workspace fitted' : 'Compact workspace: panels collapsed' });
    },
    beginDrag(panelId) {
      if (!KNOWN_PANELS.has(panelId)) { set({ error: 'unknown-panel', drag: null }); return; }
      set({ drag: { panelId, preview: null }, error: null, status: `Moving ${panelId}` });
    },
    previewDrag(input) {
      const { drag, layout, geometry } = get();
      if (!drag) return;
      const preview = resolveDockDropPreview({ ...input, layout, known: KNOWN_PANELS,
        panelId: drag.panelId,
        minimumStageWidth: geometry?.minStageWidth ?? MIN_STAGE_WIDTH,
        minimumStageHeight: geometry?.minStageHeight ?? MIN_STAGE_HEIGHT });
      set({ drag: { panelId: drag.panelId, preview }, error: null });
    },
    cancelDrag() { set({ drag: null, error: null, status: 'Move cancelled' }); },
    commitDrag() {
      const { drag, layout, geometry } = get();
      if (!drag?.preview) { set({ drag: null, status: 'No docking target' }); return false; }
      const result = dockPanel(layout, drag.panelId, drag.preview.dock, drag.preview.position,
        KNOWN_PANELS, geometry ?? undefined);
      if (!result.ok) { set({ drag: null, error: result.reason }); return false; }
      set({ layout: result.layout, drag: null, error: null, status: `${drag.panelId} docked` });
      return true;
    },
    savePreset() {
      try {
        const raw = serializePreset(get().layout, KNOWN_PANELS);
        set({ error: null, status: 'Workspace preset saved' });
        return raw;
      } catch { set({ error: 'Invalid workspace preset' }); return null; }
    },
    restorePreset(raw) {
      const parsed = parsePreset(raw, KNOWN_PANELS);
      // Presets are local to one studio and must retain every available panel.
      const ids = parsed ? [...Object.values(parsed.docks).flat(), ...parsed.floating.map(f => f.panelId)] : [];
      if (!parsed || parsed.studioId !== studioId || PANEL_IDS.some(id => !ids.includes(id))) {
        set({ error: 'Invalid workspace preset', drag: null }); return false;
      }
      const geometry = get().geometry;
      const layout = geometry ? fitWorkspace(parsed, geometry) : parsed;
      if (!layout) { set({ error: 'invalid-geometry', drag: null }); return false; }
      set({ layout, drag: null, error: null, status: 'Workspace preset restored' });
      return true;
    },
    reset() {
      const geometry = get().geometry;
      const defaults = createDefaultLayout(studioId);
      set({ layout: geometry ? fitWorkspace(defaults, geometry) ?? defaults : defaults,
        drag: null, error: null, status: 'Workspace reset' });
    },
  }));
}

/** Compact activation migrates a side panel once; switching tabs preserves order. */
export function actOnPanel(store: ReturnType<typeof createStudioWorkspaceStore>, id: string, kind: DockAction, compact: boolean) {
  const current = store.getState();
  if (compact && (kind === 'activate' || kind === 'expand')) {
    if (!current.layout.docks.bottom.includes(id)) {
      const target = dockPanel(current.layout, id, 'bottom', current.layout.docks.bottom.length,
        KNOWN_PANELS, current.geometry ?? undefined);
      if (target.ok) store.setState({ layout: target.layout });
    }
    const next = store.getState();
    if (next.layout.docks.bottom.includes(id) && next.layout.sizes.bottomFraction !== 0.5) next.resize('bottom', 0.5);
  }
  return store.getState().action(id, kind);
}
